From 99985661f6b5ebf93390f305fb6352189df37cd5 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 19:48:45 +0100
Subject: [PATCH] applet: let users pin favorite devices above the others

With many paired devices the ones used every day could end up far down
the alphabetical list. Each device now has an "Add to Favorites" action,
and favorites are listed in their own section above the other devices.

BUG: 490982
---
 src/applet/devicesproxymodel.cpp      | 34 +++++++++++++++++++++++++++
 src/applet/devicesproxymodel.h        |  7 ++++++
 src/applet/main.xml                   |  4 ++++
 src/applet/qml/DeviceItem.qml         | 15 ++++++++++++
 src/applet/qml/FullRepresentation.qml |  1 +
 5 files changed, 61 insertions(+)

diff --git a/src/applet/devicesproxymodel.cpp b/src/applet/devicesproxymodel.cpp
index bea49e5c..6bb7e108 100644
--- a/src/applet/devicesproxymodel.cpp
+++ b/src/applet/devicesproxymodel.cpp
@@ -48,6 +48,22 @@ void DevicesProxyModel::setUnpairedOnly(bool unpairedOnly)
     }
 }

+QStringList DevicesProxyModel::favoriteAddresses() const
+{
+    return m_favoriteAddresses;
+}
+
+void DevicesProxyModel::setFavoriteAddresses(const QStringList &addresses)
+{
+    if (m_favoriteAddresses != addresses) {
+        m_favoriteAddresses = addresses;
+
+        invalidate();
+
+        Q_EMIT favoriteAddressesChanged();
+    }
+}
+
 QHash<int, QByteArray> DevicesProxyModel::roleNames() const
 {
     QHash<int, QByteArray> roles = QSortFilterProxyModel::roleNames();
@@ -66,6 +82,9 @@ QVariant DevicesProxyModel::data(const QModelIndex &index, int role) const
         if (index.data(BluezQt::DevicesModel::ConnectedRole).toBool()) {
             return i18nc("@title:column Connected Bluetooth devices", "Connected");
         }
+        if (isFavorite(index)) {
+            return i18nc("@title:column Favorite Bluetooth devices", "Favorites");
+        }
         return i18nc("@title:column Available but not connected Bluetooth devices", "Available");

     case DeviceFullNameRole:
@@ -107,6 +126,16 @@ bool DevicesProxyModel::lessThan(const QModelIndex &left, const QModelIndex &rig
         return false;
     }

+    const bool leftFavorite = isFavorite(left);
+    const bool rightFavorite = isFavorite(right);
+
+    // Favorites go above other disconnected devices
+    if (!leftFavorite && rightFavorite) {
+        return true;
+    } else if (leftFavorite && !rightFavorite) {
+        return false;
+    }
+
     const QString &leftName = left.data(BluezQt::DevicesModel::NameRole).toString();
     const QString &rightName = right.data(BluezQt::DevicesModel::NameRole).toString();

@@ -123,6 +152,11 @@ bool DevicesProxyModel::duplicateIndexAddress(const QModelIndex &idx) const
     return list.size() > 1;
 }

+bool DevicesProxyModel::isFavorite(const QModelIndex &idx) const
+{
+    return m_favoriteAddresses.contains(idx.data(BluezQt::DevicesModel::AddressRole).toString());
+}
+
 bool DevicesProxyModel::filterAcceptsRow(int source_row, const QModelIndex &source_parent) const
 {
     const QModelIndex index = sourceModel()->index(source_row, 0, source_parent);
diff --git a/src/applet/devicesproxymodel.h b/src/applet/devicesproxymodel.h
index 7810e748..7e7213db 100644
--- a/src/applet/devicesproxymodel.h
+++ b/src/applet/devicesproxymodel.h
@@ -18,6 +18,7 @@ class DevicesProxyModel : public QSortFilterProxyModel

     Q_PROPERTY(bool hideBlockedDevices READ hideBlockedDevices WRITE setHideBlockedDevices NOTIFY hideBlockedDevicesChanged FINAL)
     Q_PROPERTY(bool unpairedOnly READ unpairedOnly WRITE setUnpairedOnly)
+    Q_PROPERTY(QStringList favoriteAddresses READ favoriteAddresses WRITE setFavoriteAddresses NOTIFY favoriteAddressesChanged FINAL)

 public:
     enum AdditionalRoles {
@@ -35,6 +36,9 @@ public:
     bool unpairedOnly() const;
     void setUnpairedOnly(bool unpairedOnly);

+    QStringList favoriteAddresses() const;
+    void setFavoriteAddresses(const QStringList &addresses);
+
     QHash<int, QByteArray> roleNames() const override;
     QVariant data(const QModelIndex &index, int role) const override;
     bool lessThan(const QModelIndex &left, const QModelIndex &right) const override;
@@ -42,10 +46,13 @@ public:

 Q_SIGNALS:
     void hideBlockedDevicesChanged();
+    void favoriteAddressesChanged();

 private:
     bool duplicateIndexAddress(const QModelIndex &idx) const;
+    bool isFavorite(const QModelIndex &idx) const;

     bool m_hideBlockedDevices = false;
     bool m_unpairedOnly = false;
+    QStringList m_favoriteAddresses;
 };
diff --git a/src/applet/main.xml b/src/applet/main.xml
index b4f27269..1f5f9314 100644
--- a/src/applet/main.xml
+++ b/src/applet/main.xml
@@ -10,6 +10,10 @@
       <label>If true, the CompactRepresentation icon will display a badge with the number of connected devices.</label>
       <default>false</default>
     </entry>
+    <entry name="favoriteDevices" type="StringList">
+      <label>Addresses of devices shown above other disconnected devices.</label>
+      <default></default>
+    </entry>
   </group>

 </kcfg>
diff --git a/src/applet/qml/DeviceItem.qml b/src/applet/qml/DeviceItem.qml
index e750926a..9a9ef3df 100644
--- a/src/applet/qml/DeviceItem.qml
+++ b/src/applet/qml/DeviceItem.qml
@@ -19,6 +19,7 @@ import org.kde.kquickcontrolsaddons as KQuickControlsAddons
 import org.kde.ksvg as KSvg
 import org.kde.plasma.components as PlasmaComponents3
 import org.kde.plasma.extras as PlasmaExtras
+import org.kde.plasma.plasmoid
 import org.kde.plasma.private.bluetooth as PlasmaBt

 PlasmaExtras.ExpandableListItem {
@@ -65,6 +66,20 @@ PlasmaExtras.ExpandableListItem {
                 PlasmaBt.LaunchApp.launchSendFile(root.model.Ubi);
             }
         },
+        QQC2.Action {
+            id: favoriteButton
+            readonly property bool favorite: Plasmoid.configuration.favoriteDevices.includes(root.model.Address)
+            icon.name: favoriteButton.favorite ? "bookmark-remove-symbolic" : "bookmark-new-symbolic"
+            text: favoriteButton.favorite ? i18nc("@action:button", "Remove from Favorites") : i18nc("@action:button", "Add to Favorites")
+
+            onTriggered: source => {
+                const favorites = Plasmoid.configuration.favoriteDevices.filter(address => address !== root.model.Address);
+                if (!favoriteButton.favorite) {
+                    favorites.push(root.model.Address);
+                }
+                Plasmoid.configuration.favoriteDevices = favorites;
+            }
+        },
         QQC2.Action {
             id: forgetButton
             icon.name: "edit-delete-remove-symbolic"
diff --git a/src/applet/qml/FullRepresentation.qml b/src/applet/qml/FullRepresentation.qml
index c281b129..c4570699 100644
--- a/src/applet/qml/FullRepresentation.qml
+++ b/src/applet/qml/FullRepresentation.qml
@@ -49,6 +49,7 @@ PlasmaExtras.Representation {
     PlasmaBt.DevicesProxyModel {
         id: devicesModel
         hideBlockedDevices: true
+        favoriteAddresses: Plasmoid.configuration.favoriteDevices
         sourceModel: PlasmaBt.SharedDevicesStateProxyModel
     }

